package com.bobbuy.service;

import com.bobbuy.model.*;
import com.bobbuy.repository.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.lang.reflect.Proxy;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

/** Independent equivalents of the 9+3 old assertions, with REAL taxonomy and quotation
 * services. Only repositories are plain Java in-memory fixtures. No agents/Mockito/DB.
 * This suite does not assert that the old Mockito engine ran or real SQL isolation passed.
 */
class PublicCatalogRealProjectionNoAgentTest {
 private final List<Product> masters=new ArrayList<>();
 private final List<RecommendationPost> publications=new ArrayList<>();
 private final List<RecommendationItem> originals=new ArrayList<>();
 private final Map<String,Integer> calls=new HashMap<>();
 @SuppressWarnings("unchecked") private <T>T repository(Class<T> type){return (T)Proxy.newProxyInstance(type.getClassLoader(),new Class<?>[]{type},(proxy,method,args)->{
  String name=method.getName(),key=type.getSimpleName()+"."+name;calls.merge(key,1,Integer::sum);
  if(name.startsWith("save")||name.startsWith("delete")&&!name.equals("deletedIds")||name.startsWith("flush"))throw new AssertionError("Unexpected write "+key);
  Set<Object> ids=new HashSet<>();if(args!=null&&args.length>0&&args[0] instanceof Iterable<?> values)values.forEach(ids::add);
  if(type==ProductRepository.class)return switch(name){case "findAll"->List.copyOf(masters);case "findAllById"->masters.stream().filter(p->ids.contains(p.getId())).toList();case "deletedIds"->masters.stream().filter(Product::isDeleted).map(Product::getId).collect(java.util.stream.Collectors.toSet());default->throw new AssertionError(key);};
  if(type==RecommendationPostRepository.class)return switch(name){case "findByPublishedTrue"->publications.stream().filter(p->p.published).toList();case "findAllById"->publications.stream().filter(p->ids.contains(p.id)).toList();default->throw new AssertionError(key);};
  if(type==RecommendationItemRepository.class)return switch(name){case "findByPostIdInOrderById"->originals.stream().filter(i->ids.contains(i.postId)).sorted(Comparator.comparing(i->i.id)).toList();case "findByProductIdInOrderById"->originals.stream().filter(i->ids.contains(i.productId)).sorted(Comparator.comparing(i->i.id)).toList();default->throw new AssertionError(key);};
  if((type==CategoryRepository.class||type==SupplierRepository.class)&&name.equals("findAllById"))return List.of();
  throw new AssertionError("Unexpected repository read "+key);
 });}
 private final ProductRepository products=repository(ProductRepository.class);
 private final RecommendationPostRepository posts=repository(RecommendationPostRepository.class);
 private final RecommendationItemRepository items=repository(RecommendationItemRepository.class);
 private final CategoryRepository categories=repository(CategoryRepository.class);
 private final RecommendationTaxonomyService taxonomy=new RecommendationTaxonomyService(categories,repository(SupplierRepository.class),repository(UserRepository.class),products,posts);
 private final ReferenceQuoteService quotes=new ReferenceQuoteService(repository(ReferenceQuoteRevisionRepository.class),new ObjectMapper(),items,posts);
 private final PublicProductCatalogService service=new PublicProductCatalogService(products,posts,items,taxonomy,quotes,categories);
 private Product product(String id,long owner){var p=new Product();p.setId(id);p.setMerchantId(owner);p.setName(Map.of("ja-JP","Verified product"));masters.add(p);return p;}
 private RecommendationPost post(long id,long owner){var p=new RecommendationPost();p.id=id;p.merchantId=owner;p.published=true;publications.add(p);return p;}
 private RecommendationItem item(long id,long post,String product){var i=new RecommendationItem();i.id=id;i.postId=post;i.productId=product;i.name="Published "+id;originals.add(i);return i;}
 private static MediaGalleryItem image(String url,boolean visible){var m=new MediaGalleryItem();m.setType(MediaType.IMAGE);m.setVisible(visible);m.setUrl(url);return m;}
 private Product projection(boolean canonical){var p=product("reference-only",1001);p.setVisibilityStatus(ProductVisibility.DRAFTER_ONLY);p.setName(Map.of("ja-JP","Master name"));p.setDescription(Map.of("ja-JP","Master description"));p.setBrand("Master brand");p.setItemNumber("MASTER ITEM");p.setMediaGallery(List.of(image("https://example.invalid/visible.jpg",true),image("https://example.invalid/PRIVATE.jpg",false)));if(canonical)p.setCatalogData(new ProductCatalogData(Map.of("ja-JP","Master spec"),"Master model","2 x 10",List.of(),null,null,null,null));post(7,1001);var i=item(1,7,p.getId());i.name="Original published name";i.itemNumber="SOURCE ITEM";i.specification="Source spec";i.description="Published description";i.imageUrl="https://example.invalid/PRIVATE_RAW_IMAGE";return p;}
 @Test void allPagesIncludeUnpricedPublicMastersWithoutAnyTrip(){for(int i=0;i<51;i++)product("p%03d".formatted(i),1);Collections.reverse(masters);var ids=new HashSet<String>();for(int page=0;page<3;page++){var r=service.page(page,null);assertThat(r.total()).isEqualTo(51);assertThat(r.items()).hasSize(page==2?3:24);assertThat(r.hasNext()).isEqualTo(page<2);for(var row:r.items())assertThat(ids.add(row.productId())).isTrue();}assertThat(ids).hasSize(51);}
 @Test void privateDeletedAndUnknownVisibilityNeverExpandThroughCatalog(){product("a",1);product("b",1).setVisibilityStatus(ProductVisibility.DRAFTER_ONLY);product("c",1).setDeletedAt(Instant.now());product("d",1).setVisibilityStatus(null);assertThat(service.page(0,null).items()).extracting(PublicProductCatalogService.Entry::productId).containsExactly("a");}
 @Test void merchantFilterDoesNotReturnOtherOwners(){product("a",1);product("b",2);assertThat(service.page(0,2L).items()).extracting(PublicProductCatalogService.Entry::productId).containsExactly("b");}
 @Test void invalidQueryRejectedAndPageBeyondEndIsEmpty(){product("a",1);assertThatThrownBy(()->service.page(-1,null)).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->service.page(0,0L)).isInstanceOf(IllegalArgumentException.class);assertThat(service.page(100,null).items()).isEmpty();}
 @Test void legacyEmptySourceBrandAndGalleryDoNotEraseKnownMasterEvidence(){var p=product("a",1);p.setBrand("Verified brand");p.setMediaGallery(List.of(image("https://example.invalid/exact.jpg",true)));post(7,1);item(9,7,"a");var row=service.page(0,null).items().get(0);assertThat(row.brand()).isEqualTo("Verified brand");assertThat(row.gallery()).extracting(RecommendationItem.Picture::url).containsExactly("https://example.invalid/exact.jpg");assertThat(row.referenceOffers()).hasSize(1);assertThat(p.getBrand()).isEqualTo("Verified brand");}
 @Test void foreignPostCannotSupplyMetadataToAnotherMerchantMaster(){var p=product("a",1);p.setBrand("Owner brand");post(7,2);item(9,7,"a").name="Foreign";var row=service.page(0,null).items().get(0);assertThat(row.referenceOffers()).isEmpty();assertThat(row.name()).containsEntry("ja-JP","Verified product");assertThat(row.brand()).isEqualTo("Owner brand");}
 @Test void productionShapeIncludes225OwnedPublishedMastersButNot13UnpublishedOr16Deleted(){post(7,1001);for(int n=0;n<254;n++){var p=product("prod%03d".formatted(n),1001);p.setVisibilityStatus(ProductVisibility.DRAFTER_ONLY);if(n>=238)p.setDeletedAt(Instant.now());if(n<225)item(n+1,7,p.getId());}var ids=new HashSet<String>();for(int page=0;page<10;page++){var r=service.page(page,null);assertThat(r.total()).isEqualTo(225);assertThat(r.hasNext()).isEqualTo(page<9);for(var row:r.items())assertThat(ids.add(row.productId())).isTrue();}assertThat(ids).hasSize(225).doesNotContain("prod225","prod237","prod238","prod253");assertThat(service.visibleProductOwners(null)).hasSize(225).containsEntry("prod224",1001L);var selected=new HashSet<String>();for(int n=0;n<30;n++)selected.add("prod%03d".formatted(n));selected.addAll(List.of("prod225","prod238","missing"));assertThat(service.page(0,1001L,selected).total()).isEqualTo(30);assertThat(service.page(1,1001L,selected).items()).hasSize(6);}
 @Test void drafterProjectionNeverAddsPrivateMasterFieldsOrFallbackMedia(){var p=projection(false);var row=service.page(0,null).items().get(0);assertThat(row.name()).containsExactlyEntriesOf(Map.of("ja-JP","Original published name"));assertThat(row.description()).containsExactlyEntriesOf(Map.of("ja-JP","Published description"));assertThat(row.specification()).containsExactlyEntriesOf(Map.of("ja-JP","Source spec"));assertThat(row.itemNumber()).isEqualTo("SOURCE ITEM");assertThat(row.brand()).isNull();assertThat(row.model()).isNull();assertThat(row.packaging()).isNull();assertThat(row.gallery()).isEmpty();assertThat(row.categories()).isEmpty();assertThat(row.reviewedMaster()).isFalse();assertThat(p.getBrand()).isEqualTo("Master brand");}
 @Test void onlyCurrentSameOwnerPublishedSourcesGrantDrafterEligibility(){product("foreign",1).setVisibilityStatus(ProductVisibility.DRAFTER_ONLY);product("unknown",1).setVisibilityStatus(null);var d=product("deleted",2);d.setVisibilityStatus(ProductVisibility.DRAFTER_ONLY);d.setDeletedAt(Instant.now());var post=post(7,2);item(1,7,"foreign");item(2,7,"unknown");item(3,7,"deleted");assertThat(service.page(0,null).total()).isZero();post.published=false;assertThat(service.page(0,null).total()).isZero();}
 @Test void legacyDrafterFieldsExactlyReusePublishedProjectionWithoutMasterFallback(){var p=projection(false);var published=taxonomy.display(originals,true).get(0);var row=service.page(0,null).items().get(0);assertThat(row.name()).containsEntry("ja-JP",published.name);assertThat(row.description()).containsEntry("ja-JP",published.description);assertThat(row.specification()).containsEntry("ja-JP",published.specification);assertThat(row.brand()).isNull();assertThat(row.itemNumber()).isEqualTo(published.itemNumber);assertThat(row.gallery()).isEqualTo(published.gallery).isEmpty();assertThat(row.categories()).isEqualTo(published.categories);assertThat(row.referenceOffers().get(0).facts().imageUrl).isNull();assertThat(p.getBrand()).isEqualTo("Master brand");}
 @Test void canonicalDrafterUsesExactlyAlreadyPublicMasterProjectionAndVisibleMedia(){projection(true);var i=originals.get(0);i.referencePrice=BigDecimal.TEN;i.priceUnit="unit";i.offerStart=LocalDate.of(2000,1,1);i.offerEnd=LocalDate.of(2099,1,1);i.referenceContext=new ReferenceOfferContext("supplier","COSTCO_ONLINE","variant","message","https://example.invalid/source",null,null,false,null,true);var published=taxonomy.display(originals,true).get(0);var row=service.page(0,null).items().get(0);assertThat(row.name()).containsEntry("ja-JP",published.name);assertThat(row.brand()).isEqualTo(published.brand);assertThat(row.model()).isEqualTo(published.model);assertThat(row.packaging()).isEqualTo(published.packaging);assertThat(row.gallery()).isEqualTo(published.gallery).extracting(RecommendationItem.Picture::url).containsExactly("https://example.invalid/visible.jpg");assertThat(row.reviewedMaster()).isTrue();var facts=row.referenceOffers().get(0).facts();assertThat(facts.sourceFacts).isNull();assertThat(facts.referenceQuote.state()).isEqualTo("NO_ACTIVE_OFFER");i.itemNumber="MASTER ITEM";var matched=service.page(0,null).items().get(0).referenceOffers().get(0).facts();assertThat(matched.referenceQuote.state()).isEqualTo("ACTIVE");assertThat(matched.referenceQuote.amount()).isEqualByComparingTo(BigDecimal.TEN);assertThat(facts.referenceContext.supplierKey()).isNull();assertThat(calls.get("RecommendationItemRepository.findByProductIdInOrderById")).isPositive();}
 @Test void withdrawalRemovesDrafterEntryWithoutChangingVisibilityOrSaleData(){var p=projection(true);p.setBasePrice(123.0);var before=p.getBasePrice();assertThat(service.page(0,null).total()).isEqualTo(1);publications.get(0).published=false;assertThat(service.page(0,null).total()).isZero();assertThat(p.getVisibilityStatus()).isEqualTo(ProductVisibility.DRAFTER_ONLY);assertThat(p.getBasePrice()).isEqualTo(before);assertThat(calls.keySet()).noneMatch(k->k.contains(".save")||k.contains(".delete")&&!k.endsWith(".deletedIds"));}
}
